CREATE TRIGGER [blackbaud].trgUpdategift
ON [blackbaud].[gift]
AFTER UPDATE
AS
BEGIN
    SET NOCOUNT ON;
    UPDATE
        [blackbaud].[gift]
    SET
        __mj_UpdatedAt = GETUTCDATE()
    FROM
        [blackbaud].[gift] AS _organicTable
    INNER JOIN
        INSERTED AS I ON
        _organicTable.[id] = I.[id];
END;
